public class Solution {
    static class SimpleHashMap<K, V> {
        private static class Node<K, V> {
            K key; V value; Node<K, V> next;
            Node(K key, V value) { this.key = key; this.value = value; }
        }

        @SuppressWarnings("unchecked")
        private Node<K, V>[] buckets = new Node[16];
        private int size = 0;

        private int index(K key) {
            if (key == null) throw new IllegalArgumentException("chave nula");
            return Math.floorMod(key.hashCode(), buckets.length);
        }

        void put(K key, V value) {
            int i = index(key);
            for (var n = buckets[i]; n != null; n = n.next) {
                if (n.key.equals(key)) { n.value = value; return; }
            }
            var novo = new Node<>(key, value);
            novo.next = buckets[i];
            buckets[i] = novo;
            size++;
            if (size > buckets.length * 0.75) resize();
        }

        V get(K key) {
            int i = index(key);
            for (var n = buckets[i]; n != null; n = n.next) {
                if (n.key.equals(key)) return n.value;
            }
            return null;
        }

        V remove(K key) {
            int i = index(key);
            Node<K, V> prev = null;
            for (var n = buckets[i]; n != null; prev = n, n = n.next) {
                if (n.key.equals(key)) {
                    if (prev == null) buckets[i] = n.next;
                    else prev.next = n.next;
                    size--;
                    return n.value;
                }
            }
            return null;
        }

        int size() { return size; }

        @SuppressWarnings("unchecked")
        private void resize() {
            Node<K, V>[] antigos = buckets;
            buckets = new Node[antigos.length * 2];
            size = 0;
            for (var head : antigos) {
                for (var n = head; n != null; n = n.next) put(n.key, n.value);
            }
        }
    }
}

