import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void putGetRemove() {
        var m = new Solution.SimpleHashMap<String, Integer>();
        m.put("a", 1); m.put("b", 2);
        assertEquals(1, m.get("a"));
        assertEquals(2, m.remove("b"));
        assertNull(m.get("b"));
        assertEquals(1, m.size());
    }

    @Test void atualizaChaveExistente() {
        var m = new Solution.SimpleHashMap<String, Integer>();
        m.put("a", 1); m.put("a", 9);
        assertEquals(9, m.get("a"));
        assertEquals(1, m.size());
    }

    @Test void resizeMantemDados() {
        var m = new Solution.SimpleHashMap<Integer, Integer>();
        for (int i = 0; i < 100; i++) m.put(i, i * 2);
        assertEquals(100, m.size());
        assertEquals(198, m.get(99));
    }

    @Test void chaveNulaFalha() {
        var m = new Solution.SimpleHashMap<String, Integer>();
        assertThrows(IllegalArgumentException.class, () -> m.put(null, 1));
    }
}
